  const rl=teinte(c,'#24426b',o=>L.pantin(o,{x:xl,F:-1,p:pl,levres:true},'L'));c.fillStyle='#e8e1d0';c.beginPath();c.ellipse(rl.tete.x,rl.tete.y+18,7,3,0,0,7);c.fill();tetes.L=rl.tete;
