  const k=Math.floor(t-T_COMPTE);if(k>=0&&k<10){const u=t-T_COMPTE-k;c.save();c.globalAlpha=1-u*.6;c.textAlign='center';c.font=(96+40*(1-u))+"px "+L.F.titre;c.lineWidth=8;c.strokeStyle='rgba(10,6,4,.85)';c.strokeText(String(COMPTE[k]),640,200);c.fillStyle=L.C.or;c.fillText(String(COMPTE[k]),640,200);c.restore()}
  if(t>T_COMPTE+10){serpentins(c,t,T_COMPTE+10);const a=seg(t,T_COMPTE+10,T_COMPTE+10.4)*(1-seg(t,T_COMPTE+12.4,T_COMPTE+13));
    if(a>0){c.save();c.globalAlpha=a;c.textAlign='center';c.font="110px "+L.F.titre;c.lineWidth=8;c.strokeStyle='rgba(10,6,4,.85)';c.strokeText('1926',640,210);c.fillStyle=L.C.or;c.fillText('1926',640,210);c.restore()}}
