  c.save();c.translate(640,360);c.rotate(-.02);c.fillStyle='#e6d9bf';c.fillRect(-250,-330,500,660);c.strokeStyle='rgba(90,62,27,.5)';c.strokeRect(-236,-316,472,632);
  if(PHOTO.complete&&PHOTO.naturalWidth){const w=420,h=w*PHOTO.naturalHeight/PHOTO.naturalWidth;c.save();c.beginPath();c.rect(-210,-300,420,470);c.clip();c.drawImage(PHOTO,-w/2,-300,w,h);c.restore()}
